import hashlib,json,pathlib,platform,statistics,subprocess,tempfile,time
root=pathlib.Path('/Users/wjc/repos/unisacc')
com=root/'unisacc.com'; ref=pathlib.Path('/tmp/unisacc-r9-parent-ref')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
report={'schema':1,'scope':'warm fresh-process -run five alternating samples; actual output and exit code equality; not cold page-cache measurement','host':platform.platform(),'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'artifact_sha256':sha(com),'artifact_bytes':com.stat().st_size,'reference_sha256':sha(ref),'cases':[]}
with tempfile.TemporaryDirectory(prefix='unisacc-r9-current-bench-') as tmp:
    empty=pathlib.Path(tmp)/'empty.c'; empty.write_text('int main(void){return 0;}\n')
    for name,src in [('calc',root/'examples/apps/calc.c'),('startup',empty)]:
        commands={'model':['/bin/sh',str(com),'-run',str(src)],'classic':[str(ref),'-run',str(src)]}
        expected=None; samples={k:[] for k in commands}
        for phase in range(6):
            order=['classic','model'] if phase%2==0 else ['model','classic']
            for kind in order:
                started=time.monotonic(); result=subprocess.run(commands[kind],cwd=root,capture_output=True,timeout=8); elapsed=time.monotonic()-started
                value=(result.returncode,result.stdout,result.stderr)
                assert result.returncode==0, (name,kind,result.returncode,result.stderr)
                if expected is None: expected=value
                assert value==expected,(name,kind,'observable difference')
                if phase: samples[kind].append(elapsed)
        report['cases'].append({'name':name,'source_sha256':sha(src),'commands':commands,'samples_seconds':samples,'median_seconds':{k:statistics.median(v) for k,v in samples.items()},'rc':expected[0],'stdout_sha256':hashlib.sha256(expected[1]).hexdigest(),'stderr_sha256':hashlib.sha256(expected[2]).hexdigest(),'equal_output':True})
assert sha(com)==report['artifact_sha256'] and sha(ref)==report['reference_sha256']
pathlib.Path('/tmp/unisacc-r9-current-bench.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'sha256':report['artifact_sha256'],'cases':[{k:v for k,v in c.items() if k in ('name','median_seconds','equal_output')} for c in report['cases']]}))
